create function public.player_picture_caption_results_projection(p_player_id uuid,p_party_code text) returns table(caption text,points integer,is_leader boolean,author_nickname text,author_color text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select result.* from public.picture_caption_results_projection((select party.id from public.parties party join public.party_members member on member.party_id=party.id where party.code=upper(trim(p_party_code)) and member.player_id=p_player_id and member.access_status='joined')) result; $$;
create function public.display_picture_caption_results_projection(p_display_session_id uuid,p_party_code text) returns table(caption text,points integer,is_leader boolean,author_nickname text,author_color text,game_session_id uuid,session_revision bigint) language sql stable security definer set search_path='' as $$ select result.* from public.picture_caption_results_projection((select party.id from public.parties party join public.display_sessions display_session on display_session.party_id=party.id where party.code=upper(trim(p_party_code)) and display_session.id=p_display_session_id and display_session.revoked_at is null)) result; $$;
revoke all on function public.player_picture_caption_results_projection(uuid,text),public.display_picture_caption_results_projection(uuid,text) from public,anon,authenticated;
grant execute on function public.player_picture_caption_results_projection(uuid,text),public.display_picture_caption_results_projection(uuid,text) to service_role;